const P=[[1,1.8],[2,3.2],[4,3.6],[6,8.4],[7,6.1],[9,7.9]];
const X0=60,Y0=40,S=42,W=420;
const px=v=>X0+v*S, py=v=>Y0+W-v*S;
const BMAX=16, BASE=400, BH=260;
export function initialState({inputs,seed}){return {selected:-1};}
export function reduce({state,event,inputs,time,seed}){
  if(event&&event.type==='action'&&event.action==='clear') return {selected:-1};
  if(event&&event.type==='select'&&typeof event.target==='string'&&event.target.indexOf('pt')===0){
    const i=parseInt(event.target.slice(2),10)-1;
    if(i>=0&&i<6) return {selected: state&&state.selected===i?-1:i};
  }
  return state?{selected:state.selected}:{selected:-1};
}
export function evaluate({inputs,time,seed,state}){
  const m=Number(inputs.slope), b=Number(inputs.intercept);
  const sel=state&&typeof state.selected==='number'?state.selected:-1;
  const o=[];
  o.push({kind:'line',id:'ax_x',from:{x:X0,y:Y0+W},to:{x:X0+W,y:Y0+W},role:'neutral'});
  o.push({kind:'line',id:'ax_y',from:{x:X0,y:Y0},to:{x:X0,y:Y0+W},role:'neutral'});
  o.push({kind:'text',id:'t0',x:X0-14,y:Y0+W+18,text:'0'});
  o.push({kind:'text',id:'tx10',x:X0+W-8,y:Y0+W+18,text:'10'});
  o.push({kind:'text',id:'ty10',x:X0-30,y:Y0+6,text:'10'});
  o.push({kind:'text',id:'xt',x:X0+W/2,y:Y0+W+40,text:'x',align:'middle'});
  o.push({kind:'text',id:'yt',x:X0-40,y:Y0+W/2,text:'y'});
  o.push({kind:'polyline',id:'fit',points:[[px(0),py(b)],[px(10),py(m*10+b)]],clip:{x:X0,y:Y0,w:W,h:W},role:'prediction'});
  const E=[],Q=[];let sse=0;
  for(let i=0;i<6;i++){const p=m*P[i][0]+b;const e=P[i][1]-p;E.push({p,e});Q.push(e*e);sse+=e*e;}
  const mse=sse/6;
  for(let i=0;i<6;i++){
    const x=P[i][0],a=P[i][1],e=E[i].e,on=i===sel;
    const side=Math.abs(e)*S, xp=px(x), dir=x>5?-1:1;
    const xa=dir>0?xp:xp-side, ya=Math.min(py(a),py(E[i].p));
    const cx0=Math.max(xa,X0),cx1=Math.min(xa+side,X0+W),cy0=Math.max(ya,Y0),cy1=Math.min(ya+side,Y0+W);
    const op=on?0.45:(sel>=0?0.05:0.1);
    if(cx1-cx0>0.5&&cy1-cy0>0.5){
      const big=cx1-cx0>26&&cy1-cy0>18;
      const sq={kind:'box',id:'sq'+(i+1),x:cx0,y:cy0,w:cx1-cx0,h:cy1-cy0,role:on?'output':'warning',opacity:op};
      o.push(sq);
      if(big&&(sel<0||on)){const lx=dir>0?cx0+14:cx1-14;o.push({kind:'text',id:'sql'+(i+1),x:lx,y:cy0+14,text:'P'+(i+1),align:'middle',role:on?'output':'neutral'});}
    }
    const y1=sdk.clamp(py(a),Y0,Y0+W),y2=sdk.clamp(py(E[i].p),Y0,Y0+W);
    if(Math.abs(y2-y1)>0.5) o.push({kind:'line',id:'err'+(i+1),from:{x:xp,y:y1},to:{x:xp,y:y2},role:on?'output':'warning'});
  }
  for(let i=0;i<6;i++){
    o.push({kind:'circle',id:'pt'+(i+1),x:px(P[i][0]),y:py(P[i][1]),w:20,text:String(i+1),role:i===sel?'output':'observed'});
  }
  o.push({kind:'text',id:'btitle',x:520,y:40,text:'Squared error per point (bars 0 to 16; arrow = off scale)'});
  o.push({kind:'line',id:'bbase',from:{x:540,y:BASE},to:{x:930,y:BASE},role:'neutral'});
  for(let i=0;i<6;i++){
    const q=Q[i],h=Math.max(1,Math.min(q,BMAX)/BMAX*BH),bx=555+i*62,on=i===sel,off=q>BMAX;
    o.push({kind:'box',id:'bar'+(i+1),x:bx,y:BASE-h,w:40,h:h,role:on?'output':'warning',opacity:on?0.9:0.6});
    let ly=BASE-h-8-(i%2)*16;
    if(off){o.push({kind:'arrow',id:'bo'+(i+1),from:{x:bx+20,y:BASE-h+14},to:{x:bx+20,y:BASE-h-4},role:'warning'});ly=BASE-h-12-(i%2)*18;}
    o.push({kind:'text',id:'bv'+(i+1),x:bx+20,y:ly,text:sdk.format(q,2),align:'middle',role:on?'output':'neutral'});
    o.push({kind:'text',id:'bl'+(i+1),x:bx+20,y:BASE+20,text:'P'+(i+1),align:'middle'});
  }
  o.push({kind:'text',id:'eq',x:520,y:446,runs:[{kind:'math',tex:'\\mathrm{MSE}=\\frac{1}{6}\\sum_{i=1}^{6}(y_i-\\hat y_i)^2'}]});
  o.push({kind:'text',id:'eqn',x:520,y:478,text:'= ('+Q.map(q=>sdk.format(q,2)).join(' + ')+') / 6'});
  o.push({kind:'text',id:'eqn2',x:520,y:498,text:'= '+sdk.format(sse,2)+' / 6 = '+sdk.format(mse,2)});
  let info='Select a point to see its error and its share of the total.';
  if(sel>=0){const e=E[sel].e,sh=sse>0?Q[sel]/sse*100:0;info='P'+(sel+1)+': error '+sdk.format(P[sel][1],2)+' - '+sdk.format(E[sel].p,2)+' = '+sdk.format(e,2)+'; squared '+sdk.format(Q[sel],2)+', '+sdk.format(sh,0)+'% of sum';}
  o.push({kind:'text',id:'info',x:520,y:522,text:info,role:sel>=0?'output':'neutral'});
  return {frame:{width:960,height:540,objects:o,readouts:[{id:'mse',value:mse},{id:'sse',value:sse}]},quantities:{mse:mse,sse:sse,selected_error:sel>=0?E[sel].e:0}};
}

